INSERT INTO ITEMS VALUES ('refine_stone','Refine Stone','consumable','material',1,50,NULL,'ช่างตีบวกใช้ 1 ก้อนทุกครั้งที่ตีบวก · ได้จากเควสล่ารายวัน (กำจัดมอนสเตอร์ 100 ตัว) หรือดรอปจากมอนสเตอร์ Lv.70 ขึ้นไป 1%','VERIFIED');
